CREATE TABLE public.teacher_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), teacher_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL CHECK (length(name) BETWEEN 1 AND 100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.teacher_groups TO authenticated;
GRANT ALL ON public.teacher_groups TO service_role;
ALTER TABLE public.teacher_groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY teacher_owns_groups ON public.teacher_groups TO authenticated USING (teacher_id=auth.uid() AND (public.has_role(auth.uid(),'teacher') OR public.has_role(auth.uid(),'admin'))) WITH CHECK (teacher_id=auth.uid() AND (public.has_role(auth.uid(),'teacher') OR public.has_role(auth.uid(),'admin')));
CREATE TABLE public.teacher_group_members (group_id uuid NOT NULL REFERENCES public.teacher_groups(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, PRIMARY KEY(group_id,student_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.teacher_group_members TO authenticated;
GRANT ALL ON public.teacher_group_members TO service_role;
ALTER TABLE public.teacher_group_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY teacher_owns_members ON public.teacher_group_members TO authenticated USING (EXISTS(SELECT 1 FROM public.teacher_groups g WHERE g.id=group_id AND g.teacher_id=auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.teacher_groups g JOIN public.students s ON s.teacher_id=g.teacher_id WHERE g.id=group_id AND s.id=student_id AND g.teacher_id=auth.uid()));
CREATE TABLE public.student_exam_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), teacher_id uuid NOT NULL REFERENCES public.profiles(id), student_id uuid NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, deck_id text NOT NULL CHECK(length(deck_id) BETWEEN 1 AND 100), title text NOT NULL, due_date date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.student_exam_assignments TO authenticated;
GRANT ALL ON public.student_exam_assignments TO service_role;
ALTER TABLE public.student_exam_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY teacher_reads_assignments ON public.student_exam_assignments FOR SELECT TO authenticated USING (teacher_id=auth.uid() OR EXISTS(SELECT 1 FROM public.students s WHERE s.id=student_id AND s.user_id=auth.uid()));
CREATE POLICY teacher_creates_assignments ON public.student_exam_assignments FOR INSERT TO authenticated WITH CHECK ((public.has_role(auth.uid(),'teacher') OR public.has_role(auth.uid(),'admin')) AND teacher_id=auth.uid() AND EXISTS(SELECT 1 FROM public.students s WHERE s.id=student_id AND s.teacher_id=auth.uid()));
CREATE POLICY teacher_deletes_assignments ON public.student_exam_assignments FOR DELETE TO authenticated USING (teacher_id=auth.uid());
CREATE INDEX student_assignment_student_idx ON public.student_exam_assignments(student_id);
COMMENT ON TABLE public.student_exam_assignments IS 'Independent practice assignments; completion is derived from verified same-bank exams after assignment, not official curricular accreditation.';